// El servidor se reinicia y 10.000 clientes reconectan. ¿Cuántos llegan en el mismo instante?
let semilla = 42;
const azar = () => { semilla = (semilla * 1664525 + 1013904223) % 4294967296; return semilla / 4294967296; };

const clientes = 10000, esperaMs = 3000;           // «retry: 3000», el valor que mandamos en el ejemplo de SSE
function pico(nombre, retraso) {
  const porVentana = new Map();                     // ventanas de 100 ms
  for (let i = 0; i < clientes; i++) {
    const v = Math.floor(retraso() / 100);
    porVentana.set(v, (porVentana.get(v) || 0) + 1);
  }
  const mayor = Math.max(...porVentana.values());
  console.log(nombre.padEnd(28), 'ventanas de 100 ms usadas:', String(porVentana.size).padStart(3), ' reconexiones en la peor ventana:', mayor);
}
pico('todos esperan lo mismo', () => esperaMs);
pico('con azar (0,5x a 1,5x)', () => esperaMs * (0.5 + azar()));
